  descricao = EXCLUDED.descricao,
  linha = EXCLUDED.linha,
  produto = EXCLUDED.produto,
  cor = EXCLUDED.cor,
  espessura = EXCLUDED.espessura,
  tipo_vidro = EXCLUDED.tipo_vidro,
  unidade_custo = EXCLUDED.unidade_custo,
  marca = EXCLUDED.marca,
  subtipo = EXCLUDED.subtipo,
  acabamento = EXCLUDED.acabamento,
  origem = EXCLUDED.origem,
  ativo = TRUE,
  alterado_em = now();

ON CONFLICT (codigo_interno) WHERE codigo_interno IS NOT NULL DO UPDATE SET
  tipo_custo = EXCLUDED.tipo_custo,
  descricao = EXCLUDED.descricao,
  linha = EXCLUDED.linha,
  produto = EXCLUDED.produto,
  cor = EXCLUDED.cor,
  espessura = EXCLUDED.espessura,
  tipo_vidro = EXCLUDED.tipo_vidro,
  unidade_custo = EXCLUDED.unidade_custo,
  marca = EXCLUDED.marca,
  subtipo = EXCLUDED.subtipo,
  acabamento = EXCLUDED.acabamento,
  origem = EXCLUDED.origem,
  ativo = TRUE,
  alterado_em = now();

-- Backfill dims nos SKUs antigos sem familia
UPDATE dt_catalogo.ctl_produtos p
SET familia = CASE
  WHEN p.produto ILIKE '%BOX%' THEN 'BOX'
  WHEN p.produto ILIKE '%PORTA%' THEN 'PORTA'
  WHEN p.produto ILIKE '%JANELA%' OR p.produto ILIKE '%MAXIM%' OR p.produto = 'VENEZIANA' THEN 'JANELA'
  WHEN p.produto ILIKE '%ESPELHO%' THEN 'ESPELHO'
  WHEN p.produto ILIKE '%GUARDA%' THEN 'GUARDA_CORPO'
  WHEN p.produto ILIKE '%FACHADA%' OR p.produto ILIKE '%PELE%' THEN 'FACHADA'
  WHEN p.produto ILIKE '%COBERTURA%' OR p.produto ILIKE '%CLARAB%' THEN 'COBERTURA'
  WHEN p.produto ILIKE '%DIVIS%' THEN 'DIVISORIA'
  WHEN p.produto ILIKE '%TAMPO%' OR p.produto ILIKE '%PRATELEIRA%' THEN 'MOVEL'
  ELSE COALESCE(p.familia, 'ESPECIAL')
END
WHERE p.familia IS NULL;

UPDATE dt_catalogo.ctl_produtos
SET marca = COALESCE(marca, 'GENERICA'),
    segmento = COALESCE(segmento, 'RESIDENCIAL'),
    acabamento = COALESCE(acabamento, 'PINTURA_ELETROSTATICA')
WHERE marca IS NULL OR segmento IS NULL OR acabamento IS NULL;

SELECT setval(
  pg_get_serial_sequence('dt_catalogo.ctl_produtos', 'id_produto'),
  (SELECT COALESCE(MAX(id_produto), 1) FROM dt_catalogo.ctl_produtos)
);
SELECT setval(
  pg_get_serial_sequence('dt_catalogo.ctl_custos', 'id_custo'),
  (SELECT COALESCE(MAX(id_custo), 1) FROM dt_catalogo.ctl_custos)
);

COMMIT;
